    lsrs r2,r4,#0x1f    @ 0805c3a0 e20f
    ldr r0, player_block_stride_0805c3e0     @ 0805c3a2 0f48
    muls r0,r2    @ 0805c3a4 5043
    movs r2,#0x8e    @ 0805c3a6 8e22
    lsls r2,r2,#0x1    @ 0805c3a8 5200
    adds r1,r1,r2    @ 0805c3aa 8918
    adds r0,r0,r1    @ 0805c3ac 4018
    ldr r0,[r0,#0x0]                         @ 0805c3ae 0068
    lsrs r0,r0,#0x11    @ 0805c3b0 400c
    ands r0,r3    @ 0805c3b2 1840
    cmp r0,#0x0                              @ 0805c3b4 0028
    bne LAB_0805c3d8                         @ 0805c3b6 0fd1
    lsrs r0,r4,#0x1f    @ 0805c3b8 e00f
    bl count_available_monster_slots         @ 0805c3ba d7f7fdf8
    cmp r0,#0x0                              @ 0805c3be 0028
    beq LAB_0805c3d8                         @ 0805c3c0 0ad0
    ldrb r1,[r5,#0x2]                        @ 0805c3c2 a978
