    lsrs r0,r0,#0x1f    @ 0805c3ce c00f
    bl find_first_available_monster_slot_for_player @ 0805c3d0 d7f710fc
    cmp r0,#0x0                              @ 0805c3d4 0028
    bge LAB_0805c3e4                         @ 0805c3d6 05da
